import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DPaNRfRs.js";var i=JSON.parse(`{"title":"Interface: ChatSuggestionsState","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://sqlrooms.org/api/ai-core/interfaces/ChatSuggestionsState.html"}]]},"headers":[],"relativePath":"api/ai-core/interfaces/ChatSuggestionsState.md","filePath":"api/ai-core/interfaces/ChatSuggestionsState.md"}`),a={name:`api/ai-core/interfaces/ChatSuggestionsState.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /api/ai-core/interfaces/ChatSuggestionsState.md for this page in Markdown format</div><p><a href="./../">@sqlrooms/ai-core</a> / ChatSuggestionsState</p><h1 id="interface-chatsuggestionsstate" tabindex="-1">Interface: ChatSuggestionsState <a class="header-anchor" href="#interface-chatsuggestionsstate" aria-label="Permalink to “Interface: ChatSuggestionsState”">​</a></h1><p>Normalized prompt-suggestions state and actions, identical in shape across both chat runtime modes.</p><p>Read via <a href="./../variables/usePromptSuggestions.html">usePromptSuggestions</a>. This is the behavior layer: no DOM, no styling. <code>send</code> and <code>isReadyToSend</code> reuse the composer&#39;s own send action and readiness signals, so a suggestion and the send control never disagree.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="mode" tabindex="-1">mode <a class="header-anchor" href="#mode" aria-label="Permalink to “mode”">​</a></h3><blockquote><p><strong>mode</strong>: <a href="./../type-aliases/ChatComposerMode.html"><code>ChatComposerMode</code></a></p></blockquote><p>Which runtime this state was sourced from.</p><hr><h3 id="visible" tabindex="-1">visible <a class="header-anchor" href="#visible" aria-label="Permalink to “visible”">​</a></h3><blockquote><p><strong>visible</strong>: <code>boolean</code></p></blockquote><p>Whether suggestions are currently visible.</p><hr><h3 id="setvisible" tabindex="-1">setVisible <a class="header-anchor" href="#setvisible" aria-label="Permalink to “setVisible”">​</a></h3><blockquote><p><strong>setVisible</strong>: (<code>visible</code>) =&gt; <code>void</code></p></blockquote><p>Sets visibility directly.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th></tr></thead><tbody><tr><td><code>visible</code></td><td><code>boolean</code></td></tr></tbody></table><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="toggle" tabindex="-1">toggle <a class="header-anchor" href="#toggle" aria-label="Permalink to “toggle”">​</a></h3><blockquote><p><strong>toggle</strong>: () =&gt; <code>void</code></p></blockquote><p>Flips visibility.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="items" tabindex="-1">items <a class="header-anchor" href="#items" aria-label="Permalink to “items”">​</a></h3><blockquote><p><strong>items</strong>: readonly <code>string</code>[]</p></blockquote><p>Runtime-supplied suggestion strings, possibly empty. Session mode has no concept of runtime-supplied suggestions and always reports an empty array; local-agent mode reports the root&#39;s <code>initialSuggestions</code>.</p><hr><h3 id="issessionempty" tabindex="-1">isSessionEmpty <a class="header-anchor" href="#issessionempty" aria-label="Permalink to “isSessionEmpty”">​</a></h3><blockquote><p><strong>isSessionEmpty</strong>: <code>boolean</code></p></blockquote><p>True when the chat has no messages and no in-progress prompt, in both modes — including a draft typed before any session exists. Branch on this instead of a <code>when</code>-style prop.</p><hr><h3 id="fill" tabindex="-1">fill <a class="header-anchor" href="#fill" aria-label="Permalink to “fill”">​</a></h3><blockquote><p><strong>fill</strong>: (<code>text</code>) =&gt; <code>void</code></p></blockquote><p>Writes <code>text</code> into the prompt without sending it.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th></tr></thead><tbody><tr><td><code>text</code></td><td><code>string</code></td></tr></tbody></table><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="send" tabindex="-1">send <a class="header-anchor" href="#send" aria-label="Permalink to “send”">​</a></h3><blockquote><p><strong>send</strong>: (<code>text</code>) =&gt; <code>void</code></p></blockquote><p>Sends <code>text</code> immediately, subject to <a href="#isreadytosend">isReadyToSend</a>. Routed through the composer&#39;s <code>send</code>, so pre-send vetoes apply.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th></tr></thead><tbody><tr><td><code>text</code></td><td><code>string</code></td></tr></tbody></table><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="isreadytosend" tabindex="-1">isReadyToSend <a class="header-anchor" href="#isreadytosend" aria-label="Permalink to “isReadyToSend”">​</a></h3><blockquote><p><strong>isReadyToSend</strong>: <code>boolean</code></p></blockquote><p>True when an item&#39;s own text could be sent: a model is resolvable (session mode) and nothing is running or summarizing. Built from the same signals as <a href="./../variables/useChatComposer.html">useChatComposer</a>&#39;s <code>canSend</code>, minus its non-empty-prompt requirement, which is the wrong question for an item supplying its own text.</p><p>Built on <code>sendBlocked</code>, not <code>needsApiKey</code>: the latter is also true for apps needing no browser key (remote <code>chatEndPoint</code>, no ai-settings slice).</p>`,56)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};